example_item.example_item_data:
schema = protobuf.load([modulepath('protobuf'), '/tests/data/sensor_stream.proto']);
filename = [tempdir(), 'stream.bin'];
protobuf.write(schema, 'SensorSample', filename, struct('timestamp_ms', {1, 2, 3}), 'Delimited', true);
d = protobuf.Decoder(schema, 'SensorSample', 'Layout', 'columns');
fid = fopen(filename, 'r');
while ~feof(fid)
  d.push(fread(fid, 5, '*uint8'));
  [C, ~, report] = d.read();
  disp([C.timestamp_ms', report.PendingBytes])
end
fclose(fid);
delete(filename);
